import sys

def read_input():
    import sys
    input = sys.stdin.read
    data = input().split()
    n = int(data[0])
    s = data[1]
    t = data[2]
    return n, s, t

def can_convert(s, t):
    if sorted(s) != sorted(t):
        return False
    return True

def min_operations(n, s, t):
    if not can_convert(s, t):
        return -1

    # Count the number of mismatches
    mismatches = 0
    for i in range(n):
        if s[i] != t[i]:
            mismatches += 1

    # Each mismatch can be resolved in one operation
    return mismatches // 2

def main():
    n, s, t = read_input()
    result = min_operations(n, s, t)
    print(result)

if __name__ == "__main__":
    main()
